import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Принцип Передачи Только Знаний","description":"","frontmatter":{},"headers":[],"relativePath":"ru/87-仅回传知识原则.md","filePath":"ru/87-仅回传知识原则.md"}'),i={name:"ru/87-仅回传知识原则.md"};function o(l,t,h,n,s,p){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="принцип-передачи-только-знании" tabindex="-1">Принцип Передачи Только Знаний <a class="header-anchor" href="#принцип-передачи-только-знании" aria-label="Permalink to &quot;Принцип Передачи Только Знаний&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>87</td></tr><tr><td>Модуль</td><td>Межплоскостное взаимодействие и правила времени</td></tr><tr><td>Ключевые слова</td><td>передача только знаний, очищение информации, запрет на возврат материи, кодирование знаний, аудит передачи</td></tr></tbody></table><h2 id="i-законодательныи-контекст-и-центральная-идея-принципа" tabindex="-1">I. Законодательный Контекст и Центральная Идея Принципа <a class="header-anchor" href="#i-законодательныи-контекст-и-центральная-идея-принципа" aria-label="Permalink to &quot;I. Законодательный Контекст и Центральная Идея Принципа&quot;">​</a></h2><p>Принцип «передачи только знаний» является одним из фундаментальных принципов межплоскостной археологии и археологии с возвратом времени Симбиотической Цивилизации Якоря, и его правовое происхождение восходит к статье 48 Симбиотической Конституции: «Никакие материя, энергия и живые существа, полученные из других плоскостей или других временных периодов, не могут быть привнесены в собственную плоскость без особого разрешения; законным результатом археологической деятельности являются только абстрактные знания и информация». Установление этого принципа является институциональным выбором, сделанным Вселенной Хэнъюань после обобщения горьких уроков ранних межплоскостных исследований.</p><p>В начале установления Симбиотической Цивилизации Якоря межплоскостные исследования находились ещё в состоянии беспорядка. Некоторые исследователи привозили в собственную плоскость материальные образцы, энергетические кристаллы и даже живых существ из других плоскостей для изучения, что вызвало ряд серьёзных «инцидентов межплоскостного загрязнения». Самым известным случаем является «инцидент с чуждым кристаллом» — энергетический кристалл, привезённый из Плоскости Проявления Энергии, из-за несовместимости его параметров законов с собственной плоскостью вызвал в сети законов собственной плоскости беспорядок законов, продолжавшийся три года, что привело к аномалиям в системах культивации трёх звёздных доменов и нанесло вред десяткам тысяч культиваторов различной степени. Последующие расследования показали, что если бы в то время соблюдался принцип «передачи только знаний», эта катастрофа могла бы быть полностью предотвращена.</p><p>Центральная идея принципа «передачи только знаний»: знания — единственный безопасный посредник в межцивилизационном обмене. Материя и энергия несут в себе информацию законов своей исходной плоскости и, попав в иную среду законов, могут вызвать непредсказуемые реакции; тогда как знания как абстрактная информация после надлежащего кодирования и очищения могут быть освобождены от отпечатков законов своей исходной плоскости и стать безопасным ресурсом, общим для плоскостей.</p><h2 id="ii-определение-и-классификация-«знании»" tabindex="-1">II. Определение и Классификация «Знаний» <a class="header-anchor" href="#ii-определение-и-классификация-«знании»" aria-label="Permalink to &quot;II. Определение и Классификация «Знаний»&quot;">​</a></h2><p>В правовых рамках принципа «передачи только знаний» «знания» имеют строгое определение и классификацию. Не вся информация может считаться «знаниями» и свободно передаваться — только абстрактная информация, прошедшая обработку «очищения информации» и подтверждённая как не несущая никакого загрязнения законами, соответствует стандарту передачи.</p><p>Знания делятся на три категории по степени абстрактности и уровню безопасности:</p><table tabindex="0"><thead><tr><th>Категория знаний</th><th>Определение</th><th>Уровень безопасности</th><th>Требование передачи</th></tr></thead><tbody><tr><td>Знания первого уровня (чисто абстрактные знания)</td><td>Абстрактные понятия, математические теоремы, логические выводы, философские идеи и т. д., полностью оторванные от материального носителя</td><td>Наивысший (зелёный)</td><td>Могут передаваться напрямую, без особого одобрения</td></tr><tr><td>Знания второго уровня (описательные знания)</td><td>Описательная информация об объективных вещах, включая исторические записи, географические данные, биологические характеристики, культурные описания и т. д.</td><td>Средний (жёлтый)</td><td>Должны пройти обработку очищения информации, передаются после одобрения Управлением Плоскостей</td></tr><tr><td>Знания третьего уровня (технические знания)</td><td>Практические знания, содержащие конкретные технические параметры, инженерные схемы, методы культивации</td><td>Более низкий (оранжевый)</td><td>Должны пройти строгое очищение информации и оценку безопасности, передаются после особого одобрения Собранием Якоря</td></tr></tbody></table><p>Следующие содержания не относятся к категории «знаний» и их передача строго запрещена: материальные образцы любой формы (включая микроорганизмы, клетки, фрагменты генов), энергетические кристаллы или устройства хранения энергии любой формы, живые существа или сущности сознания, обладающие автономным сознанием, сырые данные любой формы, не прошедшие очищение информации, а также любые технические детали, которые могут быть использованы для хищнической культивации.</p><h2 id="iii-технология-очищения-информации" tabindex="-1">III. Технология Очищения Информации <a class="header-anchor" href="#iii-технология-очищения-информации" aria-label="Permalink to &quot;III. Технология Очищения Информации&quot;">​</a></h2><p>Очищение информации — ключевое техническое звено обеспечения безопасности передаваемых знаний. Его центральная цель — полностью удалить отпечатки законов исходной плоскости, содержащиеся в сырой информации, оставив только чистое семантическое содержание. Процесс очищения информации делится на четыре этапа:</p><h3 id="_3-1-деконструкция-информации" tabindex="-1">3.1 Деконструкция информации <a class="header-anchor" href="#_3-1-деконструкция-информации" aria-label="Permalink to &quot;3.1 Деконструкция информации&quot;">​</a></h3><p>Сначала сырая информация, подлежащая передаче, подвергается структурной деконструкции, разделяясь на две части: «семантическое содержание» и «отпечаток носителя». Семантическое содержание — это абстрактный смысл, выражаемый информацией; отпечаток носителя — это параметры законов исходной плоскости, поглощённые информацией при хранении и передаче. Деконструкция информации осуществляется с помощью «алгоритма разделения семантики и носителя», который способен выявлять и разделять семантические и законные составляющие в информации.</p><h3 id="_3-2-отслоение-законов" tabindex="-1">3.2 Отслоение законов <a class="header-anchor" href="#_3-2-отслоение-законов" aria-label="Permalink to &quot;3.2 Отслоение законов&quot;">​</a></h3><p>Отделённый отпечаток носителя подвергается полному отслоению законов. Метод отслоения: информация пропускается через «канал нейтрализации законов» — специальный канал передачи, параметры законов которого установлены как полностью нейтральные; при прохождении информации все ненейтральные параметры законов, которые она несёт, поглощаются стенками канала. После отслоения законов информация больше не несёт никаких отпечатков законов исходной плоскости.</p><h3 id="_3-3-семантическая-реконструкция" tabindex="-1">3.3 Семантическая реконструкция <a class="header-anchor" href="#_3-3-семантическая-реконструкция" aria-label="Permalink to &quot;3.3 Семантическая реконструкция&quot;">​</a></h3><p>На основе отслоения законов семантическое содержание перекодируется, информация восстанавливается с использованием стандартной системы кодирования информации собственной плоскости. Семантическая реконструкция гарантирует, что переданные знания могут быть корректно прочитаны и поняты в среде законов собственной плоскости, а также дополнительно устраняет любые возможные остаточные информационные структуры исходной плоскости.</p><h3 id="_3-4-проверка-безопасности" tabindex="-1">3.4 Проверка безопасности <a class="header-anchor" href="#_3-4-проверка-безопасности" aria-label="Permalink to &quot;3.4 Проверка безопасности&quot;">​</a></h3><p>Очищенная информация должна пройти строгую проверку безопасности, включающую: обнаружение остатков законов (подтверждение, что информация не несёт никаких чуждых параметров законов), проверку семантической целостности (подтверждение, что процесс очищения не изменил семантическое содержание информации) и оценку потенциального риска (оценку социальных и безопасностных последствий, которые знания могут принести при распространении в собственной плоскости). Только информация, прошедшая все три проверки, допускается к передаче.</p><h2 id="iv-процедура-передачи-и-система-аудита" tabindex="-1">IV. Процедура Передачи и Система Аудита <a class="header-anchor" href="#iv-процедура-передачи-и-система-аудита" aria-label="Permalink to &quot;IV. Процедура Передачи и Система Аудита&quot;">​</a></h2><p>Передача знаний следует строгому процедурному управлению. Полная операция передачи включает следующие звенья:</p><ol><li><strong>Систематизация знаний</strong>: археологическая команда оформляет результаты исследований в стандартизированные документы знаний, с чётким указанием категории знаний и краткого содержания.</li><li><strong>Заявка на очищение</strong>: подаётся заявка на очищение и передачу знаний в Управление Плоскостей или Комитет Законов Времени с приложением документов знаний и разрешительных документов археологической миссии.</li><li><strong>Очищение информации</strong>: профессиональная техническая команда очищения информации проводит четырёхэтапную обработку очищения информации документов знаний.</li><li><strong>Проверка безопасности</strong>: очищенные знания проходят три проверки независимым органом проверки безопасности.</li><li><strong>Разрешённая передача</strong>: после прохождения проверок орган одобрения подписывает разрешение на передачу, и знания передаются в базу знаний собственной плоскости через зашифрованный канал сети Якоря.</li><li><strong>Внесение в архив</strong>: переданные знания после проверки базой знаний собственной плоскости официально вносятся в базу и открываются исследователям с соответствующими правами доступа.</li></ol><p>Все операции передачи должны проходить «аудит передачи». Содержание аудита включает: легальность источника переданных знаний, стандартность процесса очищения, полноту проверки безопасности и соответствие процедуры одобрения. Аудит осуществляется Управлением Аудита Передачи Знаний при Надзорном Комитете Якоря, которое ежеквартально проводит выборочные проверки всех операций передачи за текущий квартал и ежегодно — полный аудит. Результаты аудита докладываются Собранию Якоря, а краткое содержание публикуется для общественности.</p><h2 id="v-нарушения-и-правовая-ответственность" tabindex="-1">V. Нарушения и Правовая Ответственность <a class="header-anchor" href="#v-нарушения-и-правовая-ответственность" aria-label="Permalink to &quot;V. Нарушения и Правовая Ответственность&quot;">​</a></h2><p>К действиям, нарушающим принцип «передачи только знаний», относятся: самовольная передача неочищенной информации без одобрения, маскировка материальных образцов под знания для передачи, намеренное сокрытие отпечатков законов исходной плоскости в передаваемых знаниях и содействие другим в незаконной передаче.</p><p>Согласно Симбиотической Конституции и Закону об Управлении Межплоскостными Взаимодействиями, правовая ответственность за незаконную передачу включает: конфискацию незаконно переданных предметов и информации, приостановление или лишение археологических и навигационных квалификаций лица, штраф в размере не менее 10-кратной стоимости незаконно переданных предметов, лишение свободы для тяжких случаев, а для случаев, вызвавших загрязнение законами или экологический ущерб, — возмещение всех расходов на восстановление и компенсационную ответственность.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Принцип «передачи только знаний» — мудрая граница Симбиотической Цивилизации Якоря в области межплоскостного взаимодействия. Строгими определениями, зрелой технологией очищения, стандартизированной процедурой передачи и суровой правовой ответственностью он создаёт прочный «защитный экран безопасности знаний». Значение этого принципа не только в предотвращении загрязнения на физическом уровне, но прежде всего в установлении этики цивилизационного обмена — взаимодействие между цивилизациями должно иметь в центре столкновение идей, а не целью разграбление материи.</p><h2 id="связанные-документы" tabindex="-1">Связанные Документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные Документы&quot;">​</a></h2><ul><li>84-考古协议总纲 (Общий Протокол Археологии)</li><li>88-跨位面伦理准则 (Межплоскостные Этические Нормы)</li><li>66-跨位面通讯技术 (Технология Межплоскостной Связи)</li></ul>',32)])])}const b=a(i,[["render",o]]);export{c as __pageData,b as default};
